  exampleSelector,
  examplePrompt: PromptTemplate.fromTemplate(
    "User input: {input}\nSQL query: {query}"
  ),
  inputVariables: ["input", "dialect", "top_k"],
  prefix: SYSTEM_PREFIX,
  suffix: "",
});

